112:   for (let i = 0; i < line.length; i++) {
113:     const c = line[i];
114:     if (quote) { if (c === quote && line[i - 1] !== '\\') quote = null; continue; }
115:     if (c === '"' || c === "'") { quote = c; continue; }
116:     if (c === '>') {
117:       cut = i;
118:       mode = line[i + 1] === '>' ? '>>' : '>';
119:       break;
120:     }
121:   }
122:   if (cut < 0) return { line: line.trim(), mode: null, file: null };
123:   const cmd = line.slice(0, cut).trim();
124:   let file = line.slice(cut + (mode === '>>' ? 2 : 1)).trim();
125:   const m = file.match(/^([^\s]+)/);
126:   file = m ? m[1] : '';
