1392: export function tickWorld(game, minutes = 1, opts = {}) {
1393:   const rng = makeRng((game.seed ^ Math.floor(game.worldMinutes * 2654435761) ^ (game.tickCount * 97)) >>> 0);
1394:   minutes = Math.max(1, Math.round(minutes));
1395:   game.worldMinutes += minutes;
1396:   game.tickCount++;
1397:   const events = [];
1398:   const before = { money: game.player.money, mail: game.mail.length, contracts: game.contracts.length, sites: game.sites.length, heat: game.player.heat };
1399: 
1400:   // market random walk
1401:   const drift = (rng.next() - .5) * .006 + .00015;
1402:   game.market.index = clamp(game.market.index * (1 + drift), 720, 1480);
1403:   game.market.history.push(Math.round(game.market.index * 10) / 10);
1404:   if (game.market.history.length > 80) game.market.history.shift();
1405:   game.market.volume = Math.max(0, Math.round(game.market.volume * .94 + rng.int(120, 2400)));
1406:   game.market.sentiment = game.market.index > 1120 ? 'bullish' : game.market.index < 900 ? 'bearish' : 'neutral';
1407: 
1408:   // people keep moving
1409:   const npcUpdates = Math.min(6, 1 + Math.floor(minutes / 10));
1410:   for (let i = 0; i < npcUpdates; i++) {
1411:     const npc = rng.pick(game.npcs);
1412:     npc.online = rng.chance(.46);
1413:     npc.activity = rng.pick(ACTIVITIES);
1414:     npc.mood = rng.pick(['calm','busy','curious','tired','focused','wary']);
1415:     if (rng.chance(.006 * Math.min(minutes, 30))) {
1416:       npc.rep = clamp(npc.rep + rng.int(-1, 1), 0, 100);
1417:       if (rng.chance(.35)) addFeed(game, `@${npc.handle} is ${npc.activity}.`, 'info');
1418:     }
1419:   }
1420: 
1421:   // infrastructure events
1422:   const serverEvents = Math.max(1, Math.min(4, Math.ceil(minutes / 30)));
1423:   for (let i = 0; i < serverEvents; i++) {
1424:     const server = rng.pick(game.servers);
1425:     if (!server) continue;
1426:     if (server.owned) {
1427:       if (rng.chance(.015)) {
1428:         server.notes.unshift(rng.pick(MAINT_NOTES));
1429:         if (server.notes.length > 8) server.notes.length = 8;
1430:       }
1431:       continue;
1432:     }
1433:     if (server.status === 'offline' && rng.chance(.24)) {
1434:       server.status = 'online';
1435:       server.notes.unshift('Host recovered and rejoined the network.');
1436:       addFeed(game, `${server.host} is back online.`, 'info');
1437:       events.push({ type: 'recovery', text: `${server.host} recovered` });
1438:     } else if (server.status === 'maintenance' && rng.chance(.3)) {
1439:       server.status = 'online';
1440:       server.notes.unshift(rng.pick(MAINT_NOTES));
1441:     } else if (server.status === 'online' && rng.chance(.035)) {
1442:       server.status = rng.chance(.55) ? 'degraded' : rng.chance(.5) ? 'maintenance' : 'offline';
1443:       server.notes.unshift(server.status === 'degraded' ? 'Latency elevated; incident opened.' : server.status === 'maintenance' ? 'Scheduled maintenance started.' : 'Host unreachable.');
1444:       if (server.notes.length > 8) server.notes.length = 8;
1445:       if (server.status === 'offline') addFeed(game, `${server.host} went offline.`, 'bad');
1446:       events.push({ type: 'status', text: `${server.host} ${server.status}` });
1447:     }
1448:     if (server.status === 'online') {
1449:       server.traffic = Math.max(0, Math.round(server.traffic * (1 + rng.float(-.03, .04))));
1450:       if (server.vulns.some(v => !v.patched) && rng.chance(.012)) {
1451:         server.compromised = true;
1452:         server.security = clamp(server.security - rng.int(2, 8), 0, 99);
1453:         const news = addNews(game, rng, { silent: true });
1454:         events.push({ type: 'compromise', text: `${server.host} compromised` });
1455:         if (rng.chance(.5)) addFeed(game, `${server.host} shows signs of compromise.`, 'bad');
1456:       }
1457:       if (server.security < 52 && rng.chance(.018)) {
1458:         const v = makeVuln(rng, rng.pick(VULN_TYPES).name);
1459:         if (!server.vulns.some(x => x.name === v.name && !x.patched)) {
1460:           server.vulns.push(v);
1461:           server.notes.unshift(`New exposure discovered: ${v.name}.`);
1462:         }
1463:       }
1464:       if (server.vulns.some(v => !v.patched) && rng.chance(.02)) {
1465:         const v = server.vulns.find(x => !x.patched);
1466:         v.patched = true;
1467:         server.security = clamp(server.security + 2, 0, 99);
1468:       }
1469:       server.lastSeen = Date.now();
1470:     }
1471:   }
1472: 
1473:   // news + forum life
1474:   if (rng.chance(Math.min(.9, .028 * minutes))) {
1475:     const n = addNews(game, rng, { silent: false });
1476:     events.push({ type: 'news', text: n.headline });
1477:   }
1478:   if (rng.chance(Math.min(.75, .022 * minutes))) {
1479:     const forum = rng.pick(game.forums.filter(f => f.status === 'live'));
