1539:   // daily costs
1540:   const day = Math.floor(game.worldMinutes / MINUTES_PER_DAY);
1541:   if (day > (game.lastRentDay ?? 0)) {
1542:     game.lastRentDay = day;
1543:     const owned = ownedServers(game);
