1644:       i++;
1645:     }
1646:     return i;
1647:   }
1648:   try {
1649:     execBlock(0, 0);
1650:     ctx.game.stats.codeLines += source.split('\n').length;
1651:     if (out.length) ctx.print(out.join('\n'));
