1667: function stripPyComment(s) {
1668:   let quote = null;
1669:   for (let i = 0; i < s.length; i++) {
1670:     const c = s[i];
1671:     if (quote) { if (c === quote && s[i - 1] !== '\\') quote = null; continue; }
1672:     if (c === '"' || c === "'") { quote = c; continue; }
1673:     if (c === '#') return s.slice(0, i).trimEnd();
1674:   }
1675:   return s;
1676: }
1677: function splitArgs(s) {
1678:   const out = []; let cur = '', quote = null, depth = 0;
1679:   for (let i = 0; i < s.length; i++) {
1680:     const c = s[i];
1681:     if (quote) { cur += c; if (c === quote && s[i - 1] !== '\\') quote = null; continue; }
1682:     if (c === '"' || c === "'") { quote = c; cur += c; continue; }
1683:     if (c === '(' || c === '[' || c === '{') depth++;
1684:     if (c === ')' || c === ']' || c === '}') depth--;
1685:     if (c === ',' && depth === 0) { out.push(cur.trim()); cur = ''; continue; }
1686:     cur += c;
1687:   }
1688:   if (cur.trim()) out.push(cur.trim());
1689:   return out;
1690: }
