1692: /* ---------------- Bash subset ---------------- */
1693: async function runBash(ctx, source, filename) {
1694:   const lines = source.replace(/\r/g, '').split('\n');
1695:   let vars = { ...(ctx.term.env || {}) };
1696:   for (let i = 0; i < lines.length; i++) {
1697:     let line = lines[i].trim();
1698:     if (!line || line.startsWith('#!') || line.startsWith('#')) continue;
1699:     if (line.startsWith('for ')) {
1700:       const m = line.match(/^for\s+(\w+)\s+in\s+(.+?)(?:;\s*do)?$/);
1701:       if (m && (line.includes('do') || lines[i + 1]?.trim() === 'do')) {
1702:         const values = m[2].split(/\s+/).filter(Boolean);
1703:         let j = i + 1;
1704:         if (lines[j]?.trim() === 'do') j++;
1705:         const body = [];
1706:         while (j < lines.length && lines[j].trim() !== 'done') { body.push(lines[j]); j++; }
1707:         for (const val of values) {
1708:           for (const b of body) {
1709:             const sub = b.replace(new RegExp('\\$\\{' + m[1] + '\\}|\\$' + m[1] + '\\b', 'g'), val);
1710:             await execute(ctx.app, ctx.term, sub);
1711:           }
1712:         }
1713:         i = j;
1714:         continue;
1715:       }
1716:     }
1717:     if (line.startsWith('if ') && line.endsWith('; then')) {
1718:       // Skip a trivial if-block; execute the body only if the condition is a file test that passes.
1719:       let j = i + 1;
1720:       const body = [];
1721:       while (j < lines.length && lines[j].trim() !== 'fi') { body.push(lines[j]); j++; }
1722:       const test = line.match(/^if\s+\[(.*)\];\s*then/);
1723:       let pass = true;
1724:       if (test) {
1725:         const parts = test[1].trim().split(/\s+/);
1726:         if (parts[0] === '-f') pass = !!getNode(ctx.fs(), pathFor(ctx.term, parts[1]));
1727:         else if (parts[0] === '-d') pass = isDir(ctx.fs(), pathFor(ctx.term, parts[1]));
1728:       }
1729:       if (pass) for (const b of body) await execute(ctx.app, ctx.term, expandBash(b, vars, ctx));
1730:       i = j;
1731:       continue;
1732:     }
1733:     if (line.startsWith('while ') || line === 'done' || line === 'fi') continue;
1734:     const assign = line.match(/^(?:export\s+)?([A-Za-z_]\w*)=(.*)$/);
1735:     if (assign) {
1736:       let val = assign[2].replace(/^["']|["']$/g, '');
1737:       val = expandBash(val, vars, ctx);
1738:       vars[assign[1]] = val;
1739:       ctx.term.env = ctx.term.env || {};
1740:       if (line.startsWith('export')) ctx.term.env[assign[1]] = val;
1741:       continue;
1742:     }
1743:     if (line.startsWith('echo ')) {
1744:       let text = line.slice(5);
1745:       text = expandBash(text, vars, ctx);
1746:       ctx.print(text);
1747:       continue;
1748:     }
1749:     if (line.startsWith('printf ')) {
1750:       let text = line.slice(7).trim().replace(/^["']|["']$/g, '');
1751:       text = expandBash(text, vars, ctx).replace(/\\n/g, '\n');
1752:       ctx.print(text);
1753:       continue;
1754:     }
1755:     line = expandBash(line, vars, ctx);
1756:     await execute(ctx.app, ctx.term, line);
1757:   }
1758: }
1759: function expandBash(text, vars, ctx) {
1760:   let out = text.replace(/\$\(([^)]+)\)/g, (m, cmd) => {
1761:     const c = cmd.trim();
1762:     if (c === 'date') return new Date().toUTCString();
1763:     if (c.startsWith('uptime')) return 'up 3 days, 4:12';
1764:     if (c === 'whoami') return userOf(ctx.term);
1765:     if (c === 'pwd') return ctx.term.cwd;
1766:     if (c === 'hostname') return hostOf(ctx.term);
1767:     if (c.startsWith('cat ')) return readFile(ctx.fs(), pathFor(ctx.term, c.slice(4).trim())) || '';
1768:     return '';
1769:   });
1770:   out = out.replace(/\$\{([A-Za-z_]\w*)\}|\$([A-Za-z_]\w*)/g, (m, a, b) => {
1771:     const k = a || b;
1772:     return vars[k] ?? ctx.term.env?.[k] ?? '';
1773:   });
1774:   return out;
1775: }
