    }
    if (s.owned) {
      ctx.beginPath();
      ctx.arc(n.x, n.y, n.r + 2.4, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(99,200,232,.72)';
      ctx.lineWidth = 1;
      ctx.stroke();
