content.text:
Now init + event wiring. Also remove duplicate data-nav listeners in renderBrowser. Add init.

Init:
```js
function init() {
  const {game, loaded} = readSave();
  app.game = game;
  const elapsed = Date.now() - (game.lastSaved || game.lastActive || Date.now());
  if (loaded && elapsed > 120000) { try { app.offlineReport = simulateOffline(game, elapsed); } catch(e){...} }
  game.lastSaved = Date.now(); game.lastActive = Date.now();
  app.lastUnread = unreadMail(game);
  app.knownAch = new Set(Object.keys(game.achievements));
  app.lastLegal = game.legal.length;
  trimWorld();
  bindGlobalUI();
  updateAll();
  openWindow('terminal');
  app.booted = true;
  if (app.offlineReport) setTimeout(()=>showOfflineReport(app.offlineReport), 450);
  saveGame(false);
  setInterval(tickLoop, 2000);
  setInterval(updateClock, 1000);
}
document.addEventListener('DOMContentLoaded', init); // module scripts execute after DOM parsed, but safe:
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
```
Since module scripts are deferred, DOM ready. But calling init immediately is fine. Use:
```js
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
```

