400:   if (data.length < 2) return;
401:   const min = Math.min(...data), max = Math.max(...data);
402:   const span = Math.max(1, max - min);
403:   const up = data[data.length - 1] >= data[0];
404:   const color = up ? '#79e6a3' : '#e06c75';
405:   ctx.strokeStyle = 'rgba(255,255,255,.045)';
406:   ctx.lineWidth = 1;
407:   for (let y = 0; y <= h; y += 14) { ctx.beginPath(); ctx.moveTo(0, y + .5); ctx.lineTo(w, y + .5); ctx.stroke(); }
408:   const pt = i => [i / (data.length - 1) * w, h - 4 - (data[i] - min) / span * (h - 10)];
409:   ctx.beginPath();
410:   data.forEach((_, i) => { const [x, y] = pt(i); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); });
